"""Preserve local improvement, remaining recovery failures, and torque readout limits."""
from pathlib import Path
import json,time,numpy as np
B=Path(__file__).resolve().parent;R=B/'reports'
v=json.loads((R/'FOURTH_HOUR_LOCAL_RECOVERY_AND_REWARD_RATES_CPU_ACTUAL.json').read_bytes());rows=[]
for x in v['rows']:
 a=np.load(x['raw']['path'])['callback'];dyaw=np.arctan2(np.sin(a[-1,36]-a[0,36]),np.cos(a[-1,36]-a[0,36]))
 rows.append(dict(source_SHA=x['source_SHA'],public4_requested=x['public4_requested'],yaw=x['yaw'],strict_counts=x['strict_counts'],duration_s=x['duration_s'],first_failure=x['first_failure'],previous_duration_s=x['previous_duration_s'],previous_first_failure=x['previous_first_failure'],final_planar_speed_m_s=float(np.linalg.norm(a[-1,13:15])),final_yaw_error_rad=float(dyaw),actual_phase_recovery_ticks_max=x['actual_phase_recovery_ticks_max'],required_recovery_callbacks=200))
out=dict(epoch=time.time(),rows=rows,interpretation='Both new-source local jump traces take off and land under the original phase protocol and survive15s, compared with the prior source failing near1.4925s. Recovery remains0; the longest actual stable recovery run is110 callbacks, below200. Post-landing speed and yaw remain outside the original recovery conditions. These two yaw variants are deterministic small-sample MuJoCo evidence, not independent statistical trials, PhysX qualification or unique reward causality.',torque_readout_limitation='The existing46-column callback array stores the controller torque sent to MuJoCo d.ctrl, in actuator order hip,crank,wheel for each side. The added local reward-formula diagnostic uses those wheel command torques at indices2,5. It does not separately read d.actuator_force and must not be called a measured actuator-force or PhysX applied_torque readback. All original trace/code/report bytes remain retained.',rate_readout_limit='Added9-term callback rates are a read-only local formula diagnostic; they neither change control nor measure the production RewardManager/PPO return. Normal-mode extra terms are zero by the same request/attempt mask. This is not proof of full normal-behavior nonregression.',response='Continue the healthy unchanged production hour; next new source review should inspect recovery planar/yaw residuals and post-landing action/torque timeline. Do not tune the heldout set, alter phase/thresholds/request clock, add correction forces, or blindly change reward/LR/STD/physics.',no_replay_or_GPU_player_account_mutation=True)
with (R/'FOURTH_HOUR_LOCAL_INTERPRETATION_AND_TORQUE_READOUT_LIMITS_CPU_ACTUAL.json').open('x',encoding='utf8') as f:json.dump(out,f,indent=2)
